#include <random>
#include <cstdio>
#include <cstdlib>
using namespace std;

template<class E> void dump(const char* name, int nseeds, int nvals) {
    printf("== %s ==\n", name);
    for (int s = 1; s <= nseeds; s++) {
        E e(s);
        printf("%d:", s);
        for (int i = 0; i < nvals; i++) {
            auto v = e();
            printf(" %llu", (unsigned long long)v);
        }
        printf("\n");
    }
}
template<class E> void dumpd(const char* name, int nseeds, int nvals) {
    printf("== %s-ud ==\n", name);
    for (int s = 1; s <= nseeds; s++) {
        E e(s);
        uniform_real_distribution<double> d(0.0, 1.0);
        printf("%d:", s);
        for (int i = 0; i < nvals; i++) printf(" %.9f", d(e));
        printf("\n");
    }
}
int main() {
    int NS = 100, NV = 8;
    dump<mt19937>("mt19937", NS, NV);
    dumpd<mt19937>("mt19937", NS, NV);
    dump<mt19937_64>("mt19937_64", NS, NV);
    dumpd<mt19937_64>("mt19937_64", NS, NV);
    dump<minstd_rand>("minstd_rand", NS, NV);
    dumpd<minstd_rand>("minstd_rand", NS, NV);
    dump<minstd_rand0>("minstd_rand0", NS, NV);
    dump<ranlux24_base>("ranlux24_base", NS, NV);
    dump<ranlux48_base>("ranlux48_base", NS, NV);
    dump<knuth_b>("knuth_b", NS, NV);
    dumpd<default_random_engine>("default_random_engine", NS, NV);
    // glibc rand
    printf("== rand ==\n");
    for (int s = 1; s <= NS; s++) {
        srand(s);
        printf("%d:", s);
        for (int i = 0; i < NV; i++) printf(" %d", rand());
        printf("\n");
    }
    // rand as double
    printf("== rand-ud ==\n");
    for (int s = 1; s <= NS; s++) {
        srand(s);
        printf("%d:", s);
        for (int i = 0; i < NV; i++) printf(" %.9f", rand() / (RAND_MAX + 1.0));
        printf("\n");
    }
    return 0;
}

